SELECT sub.intervention_id, sub.operator_turn_id, sub.payload_text, sub.missing_evidence, sub.created_at FROM (SELECT i.id AS intervention_id, i.operator_turn_id, i.payload_text, i.missing_evidence, i.created_at FROM steering.interventions i JOIN steering.steerers st ON st.id = i.steerer_id JOIN steering.verdicts v ON v.id = i.verdict_id WHERE i.session_id = 1173418 AND st.kind = 'verifier' AND v.code = 'fired' AND i.created_at < '2026-09-24 08:22:50.453555+00'::timestamptz ORDER BY i.created_at DESC, i.id DESC LIMIT 10) sub ORDER BY sub.created_at ASC, sub.intervention_id ASC
